mapper.update:
UPDATE user_account
real_name = #{realName}, phone = #{phone}, gender = #{gender}, id_number = #{idNumber}, coach_license = #{coachLicense},
WHERE user_id = #{userId}

mapper.select:
SELECT
    (SELECT COUNT(*) FROM enrollment         WHERE student_user_id = #{userId}
                                                OR reviewed_by = #{userId} OR paid_by = #{userId})
  + (SELECT COUNT(*) FROM training_booking   WHERE student_user_id = #{userId}
                                                OR coach_user_id = #{userId}
                                                OR created_by = #{userId} OR assigned_by = #{userId})
  + (SELECT COUNT(*) FROM mock_exam          WHERE submitted_by = #{userId} OR reviewed_by = #{userId})
  + (SELECT COUNT(*) FROM exam_attempt       WHERE student_user_id = #{userId})
  + (SELECT COUNT(*) FROM withdrawal_request WHERE reviewed_by = #{userId} OR refunded_by = #{userId})
